            aOrbiterC = ((aWandererD + RotL64(aScatter, 37U)) + 0xCD01B4AACB90C6C8ULL) + aTwistOrbiterAssignSaltA[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterK = (aWandererG + RotL64(aCross, 27U)) + 0x23B543CFE8406247ULL;
            aOrbiterB = (aWandererE + RotL64(aPrevious, 54U)) + 0x89F395F9DD378E53ULL;
