            aOrbiterD = ((aOrbiterD + aOrbiterE) + 0x147B894EE7115169ULL) + aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 12U)) & S_SALT1];
            aOrbiterB = ((aOrbiterB ^ aOrbiterD) ^ 0x3A3B2F096EEFC5DDULL) ^ aTwistOrbiterUpdateSaltE[((aIndex + 4U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x44EFAF4486A086EBULL), 3U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterB) + 0xD5381066DEB14B4AULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterK) ^ 0x13F03E2F2A83DFA7ULL;
