            //
            aWandererD = aWandererD + (((RotL64(aIngress, 47U) + RotL64(aOrbiterG, 19U)) + aOrbiterD) + RotL64(aCarry, 51U));
            aWandererA = aWandererA ^ (((RotL64(aCross, 39U) + RotL64(aOrbiterE, 43U)) + aOrbiterA) + aKeyRotateAWandererUpdateSaltB[(((31U - aIndex) + 9U)) & S_SALT1]);
            aWandererH = aWandererH + ((RotL64(aScatter, 30U) + RotL64(aOrbiterC, 58U)) + aOrbiterH);
