            aWandererB = aWandererB + (((RotL64(aCross, 57U) + aOrbiterF) + RotL64(aOrbiterI, 51U)) + RotL64(aCarry, 21U));
            aWandererK = aWandererK ^ ((RotL64(aScatter, 35U) + RotL64(aOrbiterJ, 29U)) + aOrbiterD);
            aWandererE = aWandererE + ((RotL64(aPrevious, 43U) + RotL64(aOrbiterB, 5U)) + aOrbiterG);
            aWandererG = aWandererG ^ ((RotL64(aIngress, 53U) + aOrbiterA) + RotL64(aOrbiterF, 39U));
            aWandererI = aWandererI + (((RotL64(aCross, 27U) + RotL64(aOrbiterD, 47U)) + aOrbiterC) + aKeyRotateAWandererUpdateSaltA[(((31U - aIndex) + 23U)) & S_SALT1]);
