            aWandererJ = aWandererJ + ((RotL64(aIngress, 6U) + aOrbiterK) + RotL64(aOrbiterB, 24U));
            //
            aCarry = aCarry + (RotL64(aWandererC, 11U) ^ aWandererG);
            aCarry = aCarry + (RotL64(aWandererA, 21U) ^ aWandererJ);
            aCarry = aCarry + (aWandererH ^ RotL64(aWandererF, 36U));
