            //
            aOrbiterC = (aWandererG + RotL64(aCross, 40U)) + 0x78A07CA8DBE71BDEULL;
            aOrbiterG = (((aWandererF + RotL64(aPrevious, 5U)) + RotL64(aCarry, 19U)) + 0x6A848EEAF2B45C4DULL) + aKeyRotateAOrbiterAssignSaltD[(((31U - aIndex) + 17U)) & S_SALT1];
