            aOrbiterA = ((aWandererD + RotL64(aCross, 11U)) + RotL64(aCarry, 39U)) + 0x616FA77AC65EDAB1ULL;
            //
            aOrbiterC = ((aOrbiterC + aOrbiterG) + 0x4BA8C05888E03C67ULL) + aKeyRotateAOrbiterUpdateSaltF[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterC) ^ 0x4C042908D2C1B3DEULL) ^ aKeyRotateAOrbiterUpdateSaltE[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x5184FC71A9771253ULL), 51U);
