            aOrbiterF = (aOrbiterF + aOrbiterC) + 0x283F4446E92DABB7ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterF) ^ 0xB816DBFBCE3B0280ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x64A302795A1B8F6BULL), 23U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterJ) + 0xACD50C666A4D3DA1ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterE) ^ 0x07184531E58AA8B7ULL;
