            aOrbiterC = (aOrbiterC ^ aOrbiterA) ^ 0xBB2E4B70D3174EFAULL;
            aOrbiterC = RotL64((aOrbiterC * 0x4562D3E9E06D7249ULL), 3U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterE) + 0xAC3267B2D4648E2BULL) + aKeyRotateAOrbiterUpdateSaltB[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterA = ((aOrbiterA ^ aOrbiterG) ^ 0x77825CE219C29A5FULL) ^ aKeyRotateAOrbiterUpdateSaltC[((aIndex + 7U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0xBCBBBBBE73EA18CBULL), 43U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterF) + 0xC87411875BF835E4ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterK) ^ 0x595639D3026C1F26ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x359AB9ABDE7CF143ULL), 29U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterA) + 0x2034B0AEA33E69B8ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterJ) ^ 0x73F76F3712923D75ULL;
