            //
            aWandererG = aWandererG ^ ((RotL64(aCross, 21U) + aOrbiterK) + RotL64(aOrbiterA, 51U));
            aWandererB = aWandererB + ((((RotL64(aIngress, 57U) + aOrbiterG) + RotL64(aOrbiterA, 14U)) + RotL64(aCarry, 21U)) + aKeyRotateAWandererUpdateSaltF[(((31U - aIndex) + 5U)) & S_SALT1]);
            aWandererD = aWandererD ^ ((RotL64(aPrevious, 5U) + RotL64(aOrbiterE, 27U)) + aOrbiterK);
